import{_ as e,o as s,c as i,a2 as p}from"./chunks/framework.DPTp4bo7.js";const h=JSON.parse('{"title":"兼容1.5智能毛产的满仓溢流方案","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}]]},"headers":[],"relativePath":"zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production.md","filePath":"zh/page-nhFNnz7suUdKtA9LLLBMc0.md"}'),o={name:"zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production.md"};function c(t,a,d,r,l,n){return s(),i("div",null,[...a[0]||(a[0]=[p('<div class="logistics-content"><span class="logistics-source-anchor" id="兼容1-5智能毛产的满仓溢流方案" aria-hidden="true"></span><h1 id="兼容1-5智能毛产的满仓溢流方案" tabindex="-1">兼容1.5智能毛产的满仓溢流方案 <a class="header-anchor" href="#兼容1-5智能毛产的满仓溢流方案" aria-label="Permalink to &quot;兼容1\\.5智能毛产的满仓溢流方案&quot;">​</a></h1><blockquote><p>源页面 ID：<code>nhFNnz7suUdKtA9LLLBMc0</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=nhFNnz7suUdKtA9LLLBMc0" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red">满仓溢流 1.6 存在小更新，更新前请勿把新图息壤气拉回去，否则有缺分离芯的风险</span></p><p><span id="source-block-VKXHUYaSRClJpyV7H8iLB8"></span></p><span class="logistics-source-anchor" id="前言" aria-hidden="true"></span><h3 id="前言" tabindex="-1">前言： <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言：&quot;">​</a></h3><p>我们在1.5智能毛产中采用了空仓配平这种暴力配平的技术。但是随着样本量的剧增，我们发现，空仓配平由于加压的取货口长时间取货失败，即出现“失压”现象，造成壤晶线等的堵塞。</p><p>为此，开发局提供了两种思路方案：满仓震荡与满仓溢流</p><p><span id="source-block-GixtqDUEdoS2IjSB4OGMny"></span></p><span class="logistics-source-anchor" id="接下来本文讲解满仓溢流的思路-并给出安装蓝图" aria-hidden="true"></span><h2 id="接下来本文讲解满仓溢流的思路-并给出安装蓝图" tabindex="-1">接下来本文讲解满仓溢流的思路，并给出安装蓝图 <a class="header-anchor" href="#接下来本文讲解满仓溢流的思路-并给出安装蓝图" aria-label="Permalink to &quot;接下来本文讲解满仓溢流的思路，并给出安装蓝图&quot;">​</a></h2><p>本文撰写者：BEAR（借物表位于文末）（本文主要提供思路交流，在蓝图码和复制蓝图上仍然欠缺优化性）</p><p><span id="source-block-FwzKgopE0eOZE7ZLYr0CuL"></span></p><span class="logistics-source-anchor" id="核心思路" aria-hidden="true"></span><h3 id="核心思路" tabindex="-1">核心思路： <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路：&quot;">​</a></h3><p>我们首先要回答两个问题，什么是满仓溢流？满仓溢流为什么既能做到保证壤晶、分离芯供料充足，又能空仓做不到的无需加压从而避免“失压”现象的产生？</p><p>满仓溢流是指，我们在固体息壤/赤铜块的原产地，做溢流处理，将这两种壤晶/分离芯的原料优先入库，多余的息壤/赤铜块就地生成重息壤/赤铜粉末。</p><p>因为固体息壤/赤铜块优先入库，而且重息壤/赤铜粉末的原料不从仓库取货，所以我们能够保证分离芯/壤晶优先供料且供料充足</p><p>即：溢流满足优先供料，满仓保证供料充足</p><p>对于空仓配平/满仓震荡/满仓溢流，三者没有绝对的优劣性，笔者仅在此列出满仓溢流的优缺点供各位参考，根据自己的需求选用合适的方法：</p><p><span id="source-block-FW2RdpA3LHCYu22SKEYjj8"></span></p><span class="logistics-source-anchor" id="缺点" aria-hidden="true"></span><h3 id="缺点" tabindex="-1">缺点： <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点：&quot;">​</a></h3><p>1.满仓溢流要求一炉一池一机（因为我们假设入库不均匀，这也是本项目的优点带来的缺点之一），从而占地面积极大，景玉谷+首墩仅放下双中武+12息壤+单核耐压罐+4热能池，从而无任何兼容全物品可能性。</p><p>2.过多的设备带来了极大的电力损耗，景玉谷5泵，首墩10泵。</p><p>3.重息壤的产率难以统计，波动率实在是太大了，2h的报表都难以拉成一条直线。</p><p>4.（我还没想到？）</p><p><span id="source-block-XqdOgNCClJgFZ0LdJZ4s0s"></span></p><span class="logistics-source-anchor" id="优点" aria-hidden="true"></span><h3 id="优点" tabindex="-1">优点： <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点：&quot;">​</a></h3><p>1.对于息壤模块，有0-360的巨大震荡空间，同时是8+4模块，我们也支持科技树没点全的4炉/8炉玩家，只要你的息壤产量不低于壤晶/分离芯的消耗即可。</p><p>2.无视任何存货轮询优先级现象，每个炉子都自带一个溢流组件，即任何存货口抽风都不会对本结构有任何影响。</p><p>3.在息壤总取用不大于360，赤铜总取用不大于240（其实240这个上限可以加大，但是我懒）的情况下，可自由增加组件。如龙泡泡，选择市面上你喜欢的组件即可（如取货多了对你的组件限速即可），不需要额外定制加压产线；配套的壤晶、分离芯产线也可以换成市面上你喜欢的。</p><p>4.在你的铜系列、电池爆仓之后，会满速生产重息壤此时你的三个据点都只卖重息壤也能满足产劵要求。</p><p>5.除北部禁区气矿点外，无任何硬性跨区暗管要求。</p><p><span id="source-block-AkQqjf8DvpLOSWMmq8YKa7"></span></p><span class="logistics-source-anchor" id="安装参考蓝图" aria-hidden="true"></span><h2 id="安装参考蓝图" tabindex="-1">安装参考蓝图： <a class="header-anchor" href="#安装参考蓝图" aria-label="Permalink to &quot;安装参考蓝图：&quot;">​</a></h2><p>1.应龙关同1.5智能毛产，本项目无改动。</p><p>2.景玉谷：</p><p>上半为双核中武电池线：《明日方舟：终末地》蓝图 [5022电池]分享码EF0170i9147e65eIO0Ai 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4edbb777a3cd639a.q90-12870dda85e2a908.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>下半为四核息壤自适应满仓溢流，接5泵：《明日方舟：终末地》蓝图 [副基地4息壤]分享码EF018OIEEe562159UI73 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-311d4cd47d814b9b.q90-954cdcc125a71ed7.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>如果你想全换暗管左下角也留有暗管空位，每个水的准入口接1泵，惰气出口最好接2气矿点，避免暖机出现问题。</p><p>3.首墩：为八核息壤自适应满仓溢流。</p><p>《明日方舟：终末地》蓝图 [8息壤主体]分享码EF01ao6u52io8AaAoe5e 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [息壤液气]分享码EF01i1U9I341a28u72U4 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [重息壤固化]分享码EF01eaA00o12940EoAi8 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1c83441a19437f05.q90-2c7838c137e88c42.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-61694a6bccb6c926.q90-a44791dfa74e8241.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>需要接入10泵，中间的惰气暗管需要接入三个气矿，请按照准入口设置协议核心取货口，植物自启动，无需手动填入。</p><p>4.主基地：</p><p>《明日方舟：终末地》蓝图 [壤晶带小药]分享码EF012UOAA97oi845eIOo 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4e49f56beb017460.q90-4575beee9c73e449.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [赤铜预处理精炼]分享码EF01A6711u9OaE4e9ieO 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [赤铜预处理粉碎]分享码EF0170i998a4653uO0Ai 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a19c4d9f18eb5db1.q90-a6ac0df754927436.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [污水带小药]分享码EF011I934EAIoU8834O7 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [分离芯]分享码EF016u082OUuI730O83e 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [电池（小）]分享码EF015i2U19IieuoAeIoe 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-51c9afe8c13c7f16.q90-b6209d7ac1ae5bea.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [选配重息壤]分享码EF01081IO4e83iO8E179 请复制后前往游戏中使用。</p><p>这个重息壤蓝图仅给拉了息壤气到主基地的玩家使用，如果你没拉不需要放本蓝图。</p><p>灼铜零件也作为插件选用，这里不再给出蓝图码。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-152e938a0e895fc2.q90-1424ac4b4b8dc296.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>暂时就这么多？</p><p><span id="source-block-4Rgtkmau5rMjRlvjCEWZdC"></span></p><span class="logistics-source-anchor" id="借物表" aria-hidden="true"></span><h2 id="借物表" tabindex="-1">借物表： <a class="header-anchor" href="#借物表" aria-label="Permalink to &quot;借物表：&quot;">​</a></h2><p>双核中武：Xersyo</p><p>八核息壤主体：Xersyo、BEAR</p><p>四核息壤液气机：断懒</p><p>三核重息壤：言</p><p>壤晶&amp;小药：赫塔</p><p><span id="source-block-3tlSsgGr1OVgMgyYCLES9N"></span></p><span class="logistics-source-anchor" id="第二版主基地" aria-hidden="true"></span><h2 id="第二版主基地" tabindex="-1">第二版主基地： <a class="header-anchor" href="#第二版主基地" aria-label="Permalink to &quot;第二版主基地：&quot;">​</a></h2><p>2026.10.7更新</p><p>取消了协议箱以及冗杂的物流结构，仍然保存空位与闲置基段闲置基段源桩供diy使用。</p><p><span id="source-block-0NfqOk7rc2oMUoX03XG2mv"></span></p><span class="logistics-source-anchor" id="其余三个分基地与第一版无改动" aria-hidden="true"></span><h3 id="其余三个分基地与第一版无改动" tabindex="-1"><span class="mark-rose_red">其余三个分基地与第一版无改动</span> <a class="header-anchor" href="#其余三个分基地与第一版无改动" aria-label="Permalink to &quot;&lt;span class=&quot;mark-rose_red&quot;&gt;其余三个分基地与第一版无改动&lt;/span&gt;&quot;">​</a></h3><p>蓝图码不再携带基段，请自行放置基段（因为我装的时候源桩改了好几次位置，蓝图码里面不大好放）。</p><p>《明日方舟：终末地》蓝图 [小药+壤晶]分享码EF01eaA6ou5a0443oAi8 请复制后前往游戏中使用。</p><p>采种机旁多口双泵，另一个多口单泵，单口为净水节点壤废。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-34889ae02c0e5e23.q90-36110d90fcdb799c.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [小药]分享码EF01081IO4e83iu1E179 请复制后前往游戏中使用。</p><p>小药药液暗管在上一个蓝图里面。</p><p>《明日方舟：终末地》蓝图 [装备原件]分享码EF011I934EAIoUOo34O7 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [赫铜零件]分享码EF012UOe9a3UA8iaeIOo 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [灼铜零件]分享码EF01Oe4Aa6oe7I5A9oe4 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-565de5bf2a4ec99d.q90-8fa5f4f8bc6066dd.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a2058ac5d8b5feef.q90-983bb6319f0b1689.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [壤晶线防爆污水]分享码EF0193aoE573ue7U5uI2 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b19fd0eeb4cf33bd.q90-51642d08a496e0ce.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [赤铜预处理大]分享码EF01ao6u52io8Aiuoe5e 请复制后前往游戏中使用。</p><p>双口暗管4泵。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14609ab4c4788ed7.q90-062f038688336d60.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [赤铜预处理小]分享码EF01081IO4e83iuiE179 请复制后前往游戏中使用。</p><p>单口暗管双泵。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5e508c9c8d3f88d9.q90-148df49061a66e38.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [分离芯]分享码EF011I934EAIoUOO34O7 请复制后前往游戏中使用。</p><p>《明日方舟：终末地》蓝图 [电池+铜]分享码EF015i2U19IieuAEeIoe 请复制后前往游戏中使用。</p><p>单口暗管单泵。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c15c93c864afd4d5.q90-62128d63da4db08b.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [分离芯]分享码EF01U9ea3oE96O6I7Oa8 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c21f6f7ce4083120.q90-0a22bbbb116c2e7a.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p>《明日方舟：终末地》蓝图 [选配 重息壤]分享码EF01081IO4e83iuOE179 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f3adb6237981476e.q90-ee940c4449dcb999.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fe67ea544bff2484.q90-3ae09df3b14d8919.webp" alt="兼容15智能毛产的满仓溢流方案"></p><p><a href="/endfield-skydoc/zh/frequently-asked-questions-about-full-storage-overflow">关于满仓溢流的一些常见问题</a></p></div>',1)])])}const u=e(o,[["render",c]]);export{h as __pageData,u as default};
